try {
  let raw = query;
  if (raw && typeof raw === 'object') {
    raw = raw.draft_string !== undefined ? raw.draft_string : JSON.stringify(raw);
  }
  raw = String(raw);

  const parsed = JSON.parse(raw);

  if (parsed === null || typeof parsed !== 'object' || parsed.order_id === undefined || parsed.price === undefined) {
    return "Validation Failed: Missing required keys 'order_id' or 'price'.";
  }
  return "Validation Passed: JSON is valid and complete.";
} catch (err) {
  return "Validation Failed: Invalid JSON syntax. Error details: " + err.message + ". Ensure all keys and strings are wrapped in double quotes.";
}

