const out = $input.first().json.output;
let data;
try {
  data = typeof out === 'string'
    ? JSON.parse(out.replace(/```json|```/g, '').trim())
    : out;
} catch (e) {
  data = {
    json_data: String(out),
    reflection_loops: null,
    validation_status: 'Failed'
  };
}
return [{ json: {
  json_data: data.json_data,
  reflection_loops: data.reflection_loops,
  validation_status: data.validation_status
} }];
